import rospy
from typing import Any, Callable, Optional, Type
from .publisher import ROS1Publisher
from .subscriber import ROS1Subscriber
from .service import ROS1Service
from .client import ROS1Client
from ..logger.logger import logger
from ..timer import Timer


class ROS1Node:
    def __init__(self, node_name: str, anonymous: bool = False, **kwargs):
        self.node_name = node_name
        if not rospy.core.is_initialized():
            rospy.init_node(node_name, anonymous=anonymous)
        self._publishers = {}
        self._subscribers = {}
        self._services = {}
        self._clients = {}
        self._timers = []

    def create_publisher(
        self, msg_type: Type, topic: str, qos_profile: int = 10, **kwargs
    ):
        """创建发布者，使用ROS2风格的API"""
        publisher = ROS1Publisher(self, msg_type, topic, qos_profile, **kwargs)
        self._publishers[topic] = publisher
        return publisher

    def create_subscriber(
        self,
        msg_type: Type,
        topic: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs,
    ):
        """创建订阅者"""
        subscriber = ROS1Subscriber(
            self, msg_type, topic, callback, qos_profile, **kwargs
        )
        if topic not in self._subscribers:
            self._subscribers[topic] = []
        self._subscribers[topic].append(subscriber)
        return subscriber

    def create_service(
        self, srv_type: Type, service_name: str, callback: Callable, **kwargs
    ):
        """创建服务端"""
        service = ROS1Service(self, srv_type, service_name, callback, **kwargs)
        self._services[service_name] = service
        return service

    def create_client(self, srv_type: Type, service_name: str, **kwargs):
        """创建服务客户端"""
        client = ROS1Client(self, srv_type, service_name, **kwargs)
        client.wait_for_service(timeout=5.0)
        self._clients[service_name] = client
        return client

    def wait_for_service(self, service_name: str, timeout: Optional[float] = None):
        """等待服务可用

        Args:
            service_name: 服务名称
            timeout: 超时时间（秒），None表示无限等待
        """
        rospy.wait_for_service(service_name, timeout=timeout)

    def declare_parameter(self, name: str, value: Any = None, **kwargs):
        """声明参数"""
        if value is not None:
            rospy.set_param(f"~{name}", value)
        return self.get_parameter(name)

    def get_parameter(
        self, name: str, default: Any = None, node_name: Optional[str] = None
    ):
        """获取参数

        Args:
            name: 参数名称
            default: 默认值
            node_name: 节点名称，如果指定则获取其他节点的参数，否则获取当前节点的参数
        """
        if node_name:
            # 获取其他节点的参数
            param_name = f"/{node_name}/{name}"
        else:
            # 获取当前节点的参数
            param_name = f"~{name}"

        if rospy.has_param(param_name):
            return rospy.get_param(param_name)
        return default

    def set_parameter(self, name: str, value: Any):
        """设置参数"""
        rospy.set_param(f"~{name}", value)

    def has_parameter(self, name: str) -> bool:
        """检查参数是否存在"""
        return rospy.has_param(f"~{name}")

    def create_timer(self, period: float, callback: Callable):
        """创建定时器

        Args:
            period: 定时器周期（秒）
            callback: 回调函数
        """
        timer = Timer(period, callback)
        self._timers.append(timer)
        return timer

    def get_logger(self):
        """获取日志器（兼容ROS2风格）"""
        return logger

    def spin(self):
        """开始节点循环"""
        rospy.spin()

    def destroy_node(self):
        """销毁节点"""
        for publisher in self._publishers.values():
            publisher.destroy()
        for subscriber_list in self._subscribers.values():
            for subscriber in subscriber_list:
                subscriber.destroy()
        for service in self._services.values():
            service.destroy()
        for client in self._clients.values():
            client.destroy()
        for timer in self._timers:
            timer.shutdown()
        self._publishers.clear()
        self._subscribers.clear()
        self._services.clear()
        self._clients.clear()
        self._timers.clear()
